const trig = $('Sub-workflow Input').first()?.json || {};
const ctx = $('Resolve Tenant Context').first()?.json || {};
const scope = String(trig.scope || 'invoices').toLowerCase();
const limit = Math.min(parseInt(trig.limit, 10) || 10, 50);
const recordId = String(trig.recordId || '').trim();
const query = String(trig.query || '').trim();
const orgCfg = (ctx.orgConfig && typeof ctx.orgConfig === 'object') ? ctx.orgConfig : {};
const fbCfg = (trig.fallbackOrgConfig && typeof trig.fallbackOrgConfig === 'object') ? trig.fallbackOrgConfig : {};
const cfg = Object.assign({}, fbCfg, orgCfg);
const envelope = {
  ok: false, status: 'refused', reasonCode: 'none', guidance: 'none', userMessage: null,
  connectorId: 'zoho.books', organizationId: ctx.organizationId || null, userId: ctx.userId || null,
  contextSource: ctx.contextSource || 'fallback', degraded: ctx.degraded === true,
  records: [], total: 0, error: null,
  diagnostics: { requestId: 'zbo-' + ($execution.id || 'na') + '-' + Date.now(), workflow: 'prism-15-zoho-books-service', scope: scope }
};
function refuse(code, msg, guidance) { envelope.status = 'refused'; envelope.reasonCode = code; envelope.userMessage = msg; envelope.guidance = guidance; return [{ json: envelope }]; }
if (ctx.enabled === false) return refuse('connector_disabled', 'Zoho Books is turned off for you - enable it in Connections.', 'enable');
if (ctx.entitlement === false) return refuse('not_entitled', 'Your account does not have access to Zoho Books - ask your admin to unlock it.', 'request_access');
if (!ctx.accessToken) return refuse('missing_token', 'Zoho Books is not connected yet - connect your account in Connections to get started.', 'connect');
const dc = String(cfg.dataCenter || 'in').replace(/^zoho\./, '');
const apiBase = 'https://www.zohoapis.' + dc + '/books/v3';
// Accept the field under any of the names used across the pipeline:
// server orgConfig sends booksOrgId; the frontend fallback path sends organizationId.
const booksOrgId = String(cfg.booksOrgId || cfg.booksOrganizationId || cfg.organizationId || '').trim();
if (!booksOrgId) return refuse('org_misconfigured', 'Your organization has not configured its Zoho Books organization id yet - ask your admin to set it in organization settings.', 'none');
let url = '';
if (scope === 'customer' || scope === 'customers' || scope === 'contacts') {
  url = recordId ? apiBase + '/customers/' + encodeURIComponent(recordId) + '?organization_id=' + booksOrgId : apiBase + '/customers?organization_id=' + booksOrgId + '&per_page=' + limit;
} else if (scope === 'estimate' || scope === 'estimates') {
  url = apiBase + '/estimates?organization_id=' + booksOrgId + '&per_page=' + limit;
} else {
  url = recordId ? apiBase + '/invoices/' + encodeURIComponent(recordId) + '?organization_id=' + booksOrgId : apiBase + '/invoices?organization_id=' + booksOrgId + '&per_page=' + limit;
}
return [{ json: Object.assign({}, envelope, { ok: true, status: 'pending', accessToken: ctx.accessToken, requestUrl: url }) }];

const res = $input.first()?.json || {};
const meta = $('Gate & Build Request').first()?.json || {};
const scope = (meta.diagnostics && meta.diagnostics.scope) || 'unknown';
const envelope = {
  ok: false, status: 'error', reasonCode: 'provider_error', guidance: 'retry',
  userMessage: 'Zoho Books returned an error - try again shortly. If it persists, check the connection in Connections.',
  connectorId: 'zoho.books', organizationId: meta.organizationId || null, userId: meta.userId || null,
  contextSource: meta.contextSource || 'fallback', degraded: meta.degraded === true,
  records: [], total: 0, error: null,
  diagnostics: { requestId: (meta.diagnostics && meta.diagnostics.requestId) || ('zbo-' + Date.now()), workflow: 'prism-15-zoho-books-service' }
};
const httpStatus = (res.error && (res.error.status || res.error.statusCode)) || res.statusCode || null;
const errCode = res.error && res.error.code ? String(res.error.code) : '';
function finishSuccess() { envelope.ok = true; envelope.status = 'success'; envelope.reasonCode = 'none'; envelope.guidance = 'none'; envelope.userMessage = null; envelope.error = null; }
if (res.code === 'AUTHENTICATION_FAILURE' || res.code === 'INVALID_TOKEN') { envelope.reasonCode = 'reauth_required'; envelope.guidance = 'reconnect'; envelope.userMessage = 'Your Zoho connection needs re-authentication - reconnect in Connections.'; envelope.error = { provider: 'zoho', httpStatus: httpStatus || 401, message: String(res.code), retryable: false }; return [{ json: envelope }]; }
const raw = Array.isArray(res.invoices) ? res.invoices : (Array.isArray(res.customers) ? res.customers : (Array.isArray(res.estimates) ? res.estimates : []));
const records = raw.map(function (d) { return {
  id: String(d.invoice_id || d.customer_id || d.estimate_id || d.id || ''),
  number: d.invoice_number || d.customer_name || d.estimate_number || '',
  customer: d.customer_name || '', status: d.status || '',
  total: d.total != null ? Number(d.total) : 0, balance: d.balance != null ? Number(d.balance) : 0,
  dueDate: d.due_date || '', date: d.date || ''
}; });
finishSuccess(); envelope.records = records; envelope.total = records.length;
return [{ json: envelope }];
